diff --git a/apps/node/src/main.rs b/apps/node/src/main.rs
--- a/apps/node/src/main.rs
+++ b/apps/node/src/main.rs
@@ -497,9 +497,35 @@
     if request.goal.trim().is_empty() {
         return Err(ApiError::bad_request("agent goal must not be empty"));
     }
-    if state.agents.get(&request.backend).is_none() {
+    if request.skills.len() > 8 {
+        return Err(ApiError::bad_request(
+            "at most 8 skills may be selected for one task",
+        ));
+    }
+    for skill_name in &request.skills {
+        let skill = state
+            .skills
+            .get(skill_name, None)
+            .await
+            .map_err(ApiError::internal)?
+            .ok_or_else(|| ApiError::bad_request(format!("unknown skill {skill_name:?}")))?;
+        if !skill.summary.invocation.user_invocable {
+            return Err(ApiError::bad_request(format!(
+                "skill {skill_name:?} is not user-invocable"
+            )));
+        }
+        action_gate(
+            request.approval.granted_level,
+            request.approval.approved,
+            "skill",
+            &format!("invoke:{skill_name}"),
+            skill.summary.required_permission,
+            true,
+        )?;
+    }
+    if request.backend != "auto" && state.agents.get(&request.backend).is_none() {
         return Err(ApiError::bad_request(format!(
             "unknown agent backend {:?}",
             request.backend
         )));
     }
